import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './Crud.css';

function Crud() {
    const [tablaSeleccionada, setTablaSeleccionada] = useState('');
    const [data, setData] = useState([]);
    const [form, setForm] = useState({}); // Dynamic form based on selected table

    // Fetch data dynamically based on the selected table
    const fetchData = async () => {
        try {
            const res = await axios.get(`http://127.0.0.1:5000/api/${tablaSeleccionada.toLowerCase()}`);
            setData(res.data);
        } catch (error) {
            console.error(`Error fetching ${tablaSeleccionada}:`, error);
        }
    };

    useEffect(() => {
        if (tablaSeleccionada) {
            fetchData();
        }
    }, [tablaSeleccionada]);

    // Handle form submission dynamically based on the selected table
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await axios.post(`http://127.0.0.1:5000/api/${tablaSeleccionada.toLowerCase()}`, form);
            setForm({});
            fetchData();
        } catch (error) {
            console.error(`Error creating ${tablaSeleccionada}:`, error);
        }
    };

    // Render form fields dynamically based on the selected table
    const renderFormFields = () => {
        if (tablaSeleccionada === 'Catequizandos') {
            return (
                <>
                    <label className="form-label">Nombres</label>
                    <input
                        placeholder="Nombres"
                        value={form.nombres || ''}
                        onChange={(e) => setForm({ ...form, nombres: e.target.value })}
                        required
                    />
                    <label className="form-label">Apellidos</label>
                    <input
                        placeholder="Apellidos"
                        value={form.apellidos || ''}
                        onChange={(e) => setForm({ ...form, apellidos: e.target.value })}
                        required
                    />
                    <label className="form-label">Contacto</label>
                    <input
                        placeholder="Contacto"
                        value={form.contacto || ''}
                        onChange={(e) => setForm({ ...form, contacto: e.target.value })}
                        required
                    />
                    <label className="form-label">Fecha de Nacimiento</label>
                    <input
                        type="date"
                        value={form.fechaNacimiento || ''}
                        onChange={(e) => setForm({ ...form, fechaNacimiento: e.target.value })}
                        required
                    />
                    <label className="form-label">Fe Bautismo</label>
                    <input
                        type="checkbox"
                        checked={form.feBautismo || false}
                        onChange={(e) => setForm({ ...form, feBautismo: e.target.checked })}
                    />
                </>
            );
        } else if (tablaSeleccionada === 'Parroquias') {
            return (
                <>
                    <label className="form-label">Nombre</label>
                    <input
                        placeholder="Nombre"
                        value={form.nombre || ''}
                        onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                        required
                    />
                    <label className="form-label">Teléfono</label>
                    <input
                        placeholder="Teléfono"
                        value={form.telefono || ''}
                        onChange={(e) => setForm({ ...form, telefono: e.target.value })}
                        required
                    />
                    <label className="form-label">Dirección - Calle</label>
                    <input
                        placeholder="Calle"
                        value={form.direccion?.calle || ''}
                        onChange={(e) =>
                            setForm({
                                ...form,
                                direccion: { ...form.direccion, calle: e.target.value },
                            })
                        }
                        required
                    />
                    <label className="form-label">Dirección - Ciudad</label>
                    <input
                        placeholder="Ciudad"
                        value={form.direccion?.ciudad || ''}
                        onChange={(e) =>
                            setForm({
                                ...form,
                                direccion: { ...form.direccion, ciudad: e.target.value },
                            })
                        }
                        required
                    />
                </>
            );
        }
    };

    return (
        <div className="crud-container">
            <h2 className="crud-title">CRUD</h2>
            <form>
                <label className="form-label" htmlFor="tabla">Selecciona la tabla:</label>
                <select
                    id="tabla"
                    value={tablaSeleccionada}
                    onChange={(e) => setTablaSeleccionada(e.target.value)}
                    required
                >
                    <option value="">-- Selecciona una tabla --</option>
                    <option value="Catequizandos">Catequizandos</option>
                    <option value="Parroquias">Parroquias</option>
                </select>
            </form>

            {tablaSeleccionada && (
                <>
                    <form onSubmit={handleSubmit}>
                        {renderFormFields()}
                        <button type="submit">Crear</button>
                    </form>

                    <div className="documents-container">
                        {data.map((doc) => (
                            <div key={doc._id} className="document-card">
                                <h3>Documento ID: {doc._id}</h3>
                                {Object.entries(doc).map(([key, value]) => (
                                    <p key={key}>
                                        <strong>{key}:</strong> {typeof value === 'object' ? JSON.stringify(value) : value}
                                    </p>
                                ))}
                            </div>
                        ))}
                    </div>
                </>
            )}
        </div>
    );
}

export default Crud;
